/**
 * A host the sweep could not verify, counted across runs. `runs` is how many runs listed at
 * least one of its URLs as unverified; `urls` is how many it lists in the latest run.
 */
export interface HostRecurrence {
  host: string;
  runs: number;
  urls: number;
  lastSeen: string;
}

